// === patterns/math/sum-formulas.md#snippet-02 ===
// 1..n の総和
function sumN(int $n): int {
    return intdiv($n * ($n + 1), 2);
}

// 1..n の平方和
function sumSq(int $n): int {
    return intdiv($n * ($n + 1) * (2 * $n + 1), 6);
}

// 等比 r^0 + ... + r^(n-1)  (mod p, $r \ne 1$)
function geomSumMod(int $r, int $n, int $p): int {
    if ($r % $p === 1) return $n % $p;
    $num = (pow_mod($r, $n, $p) - 1 + $p) % $p;
    $den = inv_mod(($r - 1 + $p) % $p, $p);  // mod-arithmetic ページ参照
    return $num * $den % $p;
}

// === patterns/search/bfs.md#snippet-02 ===
/**
 * @param int $n 頂点数 (0-indexed)
 * @param array<int[]> $adj 隣接リスト
 * @param int $start 始点
 * @return int[] 各頂点への最短距離 (-1 = 到達不能)
 */
function bfs(int $n, array $adj, int $start): array {
    $dist = array_fill(0, $n, -1);
    $dist[$start] = 0;
    $queue = new SplQueue();
    $queue->enqueue($start);

    while (!$queue->isEmpty()) {
        $v = $queue->dequeue();
        foreach ($adj[$v] as $u) {
            if ($dist[$u] === -1) {
                $dist[$u] = $dist[$v] + 1;
                $queue->enqueue($u);
            }
        }
    }
    return $dist;
}

// === patterns/search/binary-search.md#snippet-01 ===

/**
 * x 以上になる最初の添字を返す。
 * 全て x 未満なら count($a) を返す。
 *
 * @param int[] $a 昇順ソート済み配列
 */
function lowerBound(array $a, int $x): int {
    $left = 0;
    $right = count($a);

    while ($left < $right) {
        $mid = intdiv($left + $right, 2);
        if ($a[$mid] < $x) {
            $left = $mid + 1;
        } else {
            $right = $mid;
        }
    }

    return $left;
}

/**
 * x より大きくなる最初の添字を返す。
 * 全て x 以下なら count($a) を返す。
 *
 * @param int[] $a 昇順ソート済み配列
 */
function upperBound(array $a, int $x): int {
    $left = 0;
    $right = count($a);

    while ($left < $right) {
        $mid = intdiv($left + $right, 2);
        if ($a[$mid] <= $x) {
            $left = $mid + 1;
        } else {
            $right = $mid;
        }
    }

    return $left;
}

/**
 * x があれば最初の添字を返す。
 * なければ -1 を返す。
 *
 * @param int[] $a 昇順ソート済み配列
 */
function binarySearch(array $a, int $x): int {
    $i = lowerBound($a, $x);
    if ($i < count($a) && $a[$i] === $x) {
        return $i;
    }
    return -1;
}

